-- 0028 — morning/evening briefings, and project monitoring
--
-- ## The property that matters for a briefing
--
-- Not what it contains. That a restart does not send a second one.
--
-- A briefing is generated by a scheduled duty, and this system's whole
-- recovery model is "read state, continue" (§6) - which means a duty that
-- crashed after sending and before recording WILL be re-attempted. Without a
-- uniqueness rule the morning briefing arrives twice, which is the failure
-- mode most likely to make a person stop reading it.
--
-- So the day is part of the identity: `(kind, scope_ref, for_date)` is unique.
-- `for_date` is a stored date rather than a function of `generated_at`,
-- because "which day is this the briefing for" is a decision about Grant's
-- timezone that the database has no business inferring from a UTC timestamp.
-- A briefing generated at 23:40 UTC may well be tomorrow's.
--
-- ## Why delivery is separate from generation
--
-- `delivered_at` is nullable and set later. §12's delivery policy routes by
-- preference and by channel, and preferences include "leave me alone today" -
-- so a briefing can legitimately be GENERATED and never SENT. Collapsing the
-- two would make a muted morning look identical to a crashed one.

begin;

create type public.briefing_kind as enum ('morning', 'evening');

create table public.briefings (
  briefing_id   uuid        primary key default gen_random_uuid(),
  kind          public.briefing_kind not null,

  -- Which day this is the briefing FOR, in Grant's local reckoning. Stored,
  -- not derived: a briefing generated at 23:40 UTC may be tomorrow's, and the
  -- database cannot know that.
  for_date      date        not null,

  -- 'grant' today; the column exists because §9's staff are identities and a
  -- per-project briefing is an obvious next step.
  scope_ref     text        not null default 'grant',

  body          text        not null,
  -- What it was built from, so a briefing that looks wrong can be explained
  -- without re-deriving it against data that has since moved.
  inputs        jsonb       not null default '{}'::jsonb,

  generated_at  timestamptz not null default app.now_utc(),
  -- Null means not sent. Legitimately null when preferences muted it, which is
  -- why this is separate from generation.
  delivered_at  timestamptz,
  delivered_to  text[]      not null default '{}'::text[],
  suppressed_reason text,

  constraint briefings_body_substantive check (length(trim(body)) >= 40),
  constraint briefings_scope_present check (length(trim(scope_ref)) > 0),
  -- Delivered means it went somewhere; not delivered means it says why not.
  -- The pairing is what stops "not sent" and "sent nowhere" from being the
  -- same state.
  constraint briefings_delivery_is_explained
    check (
      (delivered_at is not null and array_length(delivered_to, 1) >= 1)
      or (delivered_at is null)
    )
);

-- One per kind per day per scope. This is the whole anti-duplicate-briefing
-- property, and it is an index rather than a check in the generator because
-- the generator is the thing that will be re-run after a crash.
create unique index briefings_one_per_day
  on public.briefings (kind, scope_ref, for_date);

create index briefings_recent on public.briefings (generated_at desc);

comment on table public.briefings is
  '§12 morning/evening briefings. `(kind, scope_ref, for_date)` is unique so a '
  'duty re-attempted after a crash collides instead of sending a second one.';
comment on column public.briefings.for_date is
  'The day this briefing is FOR, in local reckoning. Stored rather than derived '
  'from generated_at: a briefing produced at 23:40 UTC may be tomorrow''s.';
comment on column public.briefings.delivered_at is
  'Null means not sent - legitimately so when preferences muted it. Separate '
  'from generation so a muted morning does not look like a crashed one.';

-- The body is a record of what was said. Updating delivery is allowed;
-- rewriting the content afterwards is not.
create or replace function app.protect_briefing_body()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.body is distinct from old.body
     or new.kind is distinct from old.kind
     or new.for_date is distinct from old.for_date
     or new.inputs is distinct from old.inputs then
    raise exception
      'a briefing''s content cannot be changed after it is generated. Delivery '
      'fields may be updated; what it said may not - it is a record of what '
      'Grant was told.'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

create trigger briefings_protect_body
  before update on public.briefings
  for each row execute function app.protect_briefing_body();

-- ---------------------------------------------------------------------------
-- Project monitoring
--
-- Returns one row per active project with the facts that would make a person
-- look at it. Deliberately NOT a score: a single number would need a
-- threshold, a threshold needs tuning, and the tuning always goes in the
-- direction of fewer alerts. The caller decides what is worth surfacing; this
-- decides nothing and hides nothing.
-- ---------------------------------------------------------------------------

create or replace function app.project_attention()
returns table (
  project_id uuid,
  slug text,
  name text,
  open_blockers integer,
  overdue_blockers integer,
  live_jobs integer,
  failed_jobs_24h integer,
  stalled_jobs integer,
  hours_since_sync numeric,
  has_brief boolean,
  brief_is_stale boolean
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    p.project_id, p.slug, p.name,
    (select count(*)::int from public.blockers b
      where b.project_id = p.project_id and b.state = 'open'),
    (select count(*)::int from public.blockers b
      where b.project_id = p.project_id and b.state = 'open'
        and b.real_deadline is not null and b.real_deadline <= app.now_utc()),
    (select count(*)::int from public.jobs j
      where j.project_id = p.project_id
        and j.state not in ('complete', 'cancelled', 'failed')),
    (select count(*)::int from public.jobs j
      where j.project_id = p.project_id and j.state = 'failed'
        and j.finished_at >= app.now_utc() - interval '24 hours'),
    -- "Long-running work must not look stuck" (§6) needs something that
    -- notices when it does. An hour without a state change on a live job is
    -- not necessarily wrong, but it is always worth being able to see.
    (select count(*)::int from public.jobs j
      where j.project_id = p.project_id
        and j.state not in ('complete', 'cancelled', 'failed')
        and j.updated_at <= app.now_utc() - interval '1 hour'),
    (select round(extract(epoch from (app.now_utc() - max(s.fetched_at))) / 3600, 1)
      from public.notebook_sources s where s.project_id = p.project_id),
    exists (select 1 from public.project_briefs b where b.project_id = p.project_id),
    -- A brief is stale when a source has changed since it was written. Same
    -- question `briefIsStale` asks in the application, answered here so the
    -- monitor does not need to load every fingerprint to find out.
    exists (
      select 1 from public.notebook_sources s
      where s.project_id = p.project_id
        and s.fetched_at > coalesce(
          (select max(b.generated_at) from public.project_briefs b
            where b.project_id = p.project_id),
          '-infinity'::timestamptz)
    )
  from public.projects p
  where p.status = 'active'
  order by p.name;
$$;

comment on function app.project_attention() is
  'Facts per active project, not a score. A single number would need a '
  'threshold, and a threshold always gets tuned toward fewer alerts.';

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------

alter table public.briefings enable row level security;
alter table public.briefings force  row level security;

grant select, insert on public.briefings to ai_team_app;
grant update (delivered_at, delivered_to, suppressed_reason) on public.briefings to ai_team_app;
create policy briefings_app_read on public.briefings for select to ai_team_app using (true);
create policy briefings_app_insert on public.briefings for insert to ai_team_app with check (true);
create policy briefings_app_update on public.briefings for update to ai_team_app using (true) with check (true);

grant execute on function app.project_attention() to ai_team_app;

commit;
